/*
 * A210751  Triangle of coefficients of polynomials u(n,x) jointly generated
 *          with A210752; see the Formula section.
 * https://oeis.org/A210751
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   a(n) is the n‑th term of the flattened triangle of coefficients
 *            of the polynomials u_n(x) generated by u_1(x) = 1, v_1(x) = 1,
 *            u_n(x) = (x+1)·u_{n-1}(x) + x·v_{n-1}(x) + 1, v_n(x) =
 *            (x+1)·u_{n-1}(x) + 2x·v_{n-1}(x) + 1
 * Range:     u8 n <= 24, u16 n <= 54, u32 n <= 54, u64 n <= 54, u128 n <= 54,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>   /* malloc, free */

seq_t a(idx_t n)
{
    if (n == 0)
        return (seq_t)0;   /* out of range, return 0 per convention */

    /* Allocate temporary arrays of maximum needed size (row n) */
    seq_t *u_cur   = (seq_t *)malloc((size_t)n * sizeof(seq_t));
    seq_t *v_cur   = (seq_t *)malloc((size_t)n * sizeof(seq_t));
    seq_t *u_next  = (seq_t *)malloc((size_t)n * sizeof(seq_t));
    seq_t *v_next  = (seq_t *)malloc((size_t)n * sizeof(seq_t));
    if (!u_cur || !v_cur || !u_next || !v_next) {
        /* allocation failure – return 0 as a safe fallback */
        free(u_cur); free(v_cur); free(u_next); free(v_next);
        return (seq_t)0;
    }

    /* Initial row (n = 1) */
    u_cur[0] = (seq_t)1;
    v_cur[0] = (seq_t)1;
    idx_t row_len = 1;          /* current row length */
    idx_t total   = 0;          /* number of terms before the current row */

    while (total + row_len < n) {
        idx_t next_len = row_len + 1;
        /* Compute next row into u_next / v_next */
        for (idx_t k = 0; k < next_len; ++k) {
            seq_t uj = (seq_t)0;
            seq_t vj = (seq_t)0;

            if (k < row_len) uj += u_cur[k];
            if (k > 0) uj += u_cur[k-1] + v_cur[k-1];
            if (k == 0) uj += (seq_t)1;
            u_next[k] = uj;

            if (k < row_len) vj += u_cur[k];
            if (k > 0) {
                seq_t two_v = v_cur[k-1] + v_cur[k-1];  /* 2 * v_prev[k-1] */
                vj += u_cur[k-1] + two_v;
            }
            if (k == 0) vj += (seq_t)1;
            v_next[k] = vj;
        }

        /* Swap current and next arrays for the next iteration */
        seq_t *tmp;
        tmp = u_cur;  u_cur = u_next;  u_next = tmp;
        tmp = v_cur;  v_cur = v_next;  v_next = tmp;

        total   += row_len;
        row_len  = next_len;
    }

    /* offset into the current row (0‑based) */
    idx_t offset = n - total - 1;
    seq_t result = u_cur[offset];

    /* Free allocated memory */
    free(u_cur); free(v_cur);
    free(u_next); free(v_next);

    return result;
}
